lemma PrefixLessThan(s: seq<int>, key: int, m: int)
  requires Sorted(s)
  requires 0 <= m < |s|
  requires s[m] < key
  ensures forall i :: 0 <= i <= m ==> s[i] < key
{
  forall i | 0 <= i <= m
    ensures s[i] < key
  {
    if i < m {
      assert 0 <= i < m < |s|;
      assert s[i] <= s[m];
    }
  }
}

lemma SuffixGreaterThan(s: seq<int>, key: int, m: int)
  requires Sorted(s)
  requires 0 <= m < |s|
  requires key < s[m]
  ensures forall i :: m <= i < |s| ==> key < s[i]
{
  forall i | m <= i < |s|
    ensures key < s[i]
  {
    if m < i {
      assert 0 <= m < i < |s|;
      assert s[m] <= s[i];
    }
  }
}

lemma NotPresentOutsideSplit(s: seq<int>, key: int, split: int)
  requires 0 <= split <= |s|
  requires forall i :: 0 <= i < split ==> s[i] < key
  requires forall i :: split <= i < |s| ==> key < s[i]
  ensures key !in s
{
  if key in s {
    var i :| 0 <= i < |s| && s[i] == key;
    if i < split {
      assert s[i] < key;
    } else {
      assert key < s[i];
    }
    assert false;
  }
}

method BinarySearch(a: seq<int>, key: int) returns (idx: int)
  requires Sorted(a)
  ensures -1 <= idx < |a|
  ensures idx >= 0 ==> a[idx] == key
  ensures idx == -1 ==> key !in a
{
  var lo := 0;
  var hi := |a|;

  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall i :: 0 <= i < lo ==> a[i] < key
    invariant forall i :: hi <= i < |a| ==> key < a[i]
    decreases hi - lo
  {
    var mid := lo + (hi - lo) / 2;
    assert lo <= mid < hi;

    if a[mid] == key {
      idx := mid;
      return;
    } else if a[mid] < key {
      PrefixLessThan(a, key, mid);
      lo := mid + 1;
    } else {
      assert key < a[mid];
      SuffixGreaterThan(a, key, mid);
      hi := mid;
    }
  }

  assert lo == hi;
  NotPresentOutsideSplit(a, key, lo);
  idx := -1;
}

