method Dedup(a: seq<int>) returns (r: seq<int>)
  requires Sorted(a)
  ensures StrictlySorted(r)
  ensures forall x :: x in a <==> x in r
{
  r := [];
  var i := 0;
  while i < |a|
    invariant 0 <= i <= |a|
    invariant StrictlySorted(r)
    invariant forall x :: x in r <==> x in a[..i]
    invariant |r| > 0 ==> i > 0 && r[|r|-1] == a[i-1]
    invariant i > 0 ==> |r| > 0
  {
    assert a[..i+1] == a[..i] + [a[i]];
    if |r| == 0 || r[|r|-1] != a[i] {
      if |r| > 0 {
        assert a[i-1] <= a[i];
        assert r[|r|-1] < a[i];
        forall k | 0 <= k < |r|
          ensures r[k] < a[i]
        {
          if k < |r| - 1 {
            assert r[k] < r[|r|-1];
          }
        }
      }
      var r' := r + [a[i]];
      forall p, q | 0 <= p < q < |r'|
        ensures r'[p] < r'[q]
      {
        if q < |r| {
          assert r'[p] == r[p] && r'[q] == r[q];
        } else {
          assert r'[q] == a[i];
          assert r'[p] == r[p];
        }
      }
      r := r';
    }
    i := i + 1;
  }
  assert a[..|a|] == a;
}

