    ghost var left := s[..i];
    ghost var middle := s[i + 1..j];
    ghost var right := s[j + 1..];

    assert s == left + [s[i]] + middle + [s[j]] + right;
    assert t == left + [s[j]] + middle + [s[i]] + right;

    calc {
      multiset(t);
      == multiset(left) + multiset([s[j]]) + multiset(middle)
           + multiset([s[i]]) + multiset(right);
      == multiset(left) + multiset([s[i]]) + multiset(middle)
