method MergeSorted(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
{
  out := [];
  var i := 0;
  var j := 0;
  while i < |a| || j < |b|
    invariant 0 <= i <= |a|
    invariant 0 <= j <= |b|
    invariant Sorted(out)
    invariant multiset(out) == multiset(a[..i]) + multiset(b[..j])
    invariant forall k :: 0 <= k < |out| ==> (i < |a| ==> out[k] <= a[i])
    invariant forall k :: 0 <= k < |out| ==> (j < |b| ==> out[k] <= b[j])
    decreases |a| - i + |b| - j
  {
    if j == |b| || (i < |a| && a[i] <= b[j]) {
      var x := a[i];
      assert a[..i+1] == a[..i] + [x];
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      var newOut := out + [x];
      assert forall p, q :: 0 <= p < q < |newOut| ==> newOut[p] <= newOut[q] by {
        forall p, q | 0 <= p < q < |newOut|
          ensures newOut[p] <= newOut[q]
        {
          if q < |out| {
            assert newOut[p] == out[p] && newOut[q] == out[q];
          } else {
            assert newOut[q] == x && newOut[p] == out[p];
          }
        }
      }
      out := newOut;
      i := i + 1;
      assert forall k :: 0 <= k < |out| ==> (i < |a| ==> out[k] <= a[i]) by {
        forall k | 0 <= k < |out| && i < |a|
          ensures out[k] <= a[i]
        {
          assert a[i-1] <= a[i];
        }
      }
    } else {
      var x := b[j];
      assert b[..j+1] == b[..j] + [x];
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      var newOut := out + [x];
      assert forall p, q :: 0 <= p < q < |newOut| ==> newOut[p] <= newOut[q] by {
        forall p, q | 0 <= p < q < |newOut|
          ensures newOut[p] <= newOut[q]
        {
          if q < |out| {
            assert newOut[p] == out[p] && newOut[q] == out[q];
          } else {
            assert newOut[q] == x && newOut[p] == out[p];
          }
        }
      }
      out := newOut;
      j := j + 1;
      assert forall k :: 0 <= k < |out| ==> (j < |b| ==> out[k] <= b[j]) by {
        forall k | 0 <= k < |out| && j < |b|
          ensures out[k] <= b[j]
        {
          assert b[j-1] <= b[j];
        }
      }
    }
  }
  assert a[..i] == a;
  assert b[..j] == b;
}

