    PrependSorted(b[0], rest);
    out := [b[0]] + rest;

    assert b == [b[0]] + b[1..];
    calc {
      multiset(out);
      == multiset([b[0]]) + multiset(rest);
      == multiset([b[0]]) + (multiset(a) + multiset(b[1..]));
      == multiset(a) + (multiset([b[0]]) + multiset(b[1..]));
      == multiset(a) + multiset(b);
    }

    forall x | LowerBound(x, a) && LowerBound(x, b)
      ensures LowerBound(x, out)
    {
      LowerBoundTail(x, b);
      assert LowerBound(x, b[1..]);
      assert LowerBound(x, rest);
      assert x <= b[0];
      LowerBoundPrepend(x, b[0], rest);
    }
  }
