lemma SortedFromIndex(s: seq<int>, p: int)
  requires Sorted(s)
  requires 0 <= p < |s|
  ensures forall k :: p <= k < |s| ==> s[p] <= s[k]
{
  forall k | p <= k < |s|
    ensures s[p] <= s[k]
  {
    if p < k {
      assert 0 <= p < k < |s|;
    } else {
      assert p == k;
    }
  }
}

lemma SortedToLast(s: seq<int>)
  requires Sorted(s)
  requires 0 < |s|
  ensures forall k :: 0 <= k < |s| ==> s[k] <= s[|s| - 1]
{
  forall k | 0 <= k < |s|
    ensures s[k] <= s[|s| - 1]
  {
    if k < |s| - 1 {
      assert 0 <= k < |s| - 1 < |s|;
    } else {
      assert k == |s| - 1;
    }
  }
}

lemma AppendPreservesSorted(s: seq<int>, x: int)
  requires Sorted(s)
  requires forall k :: 0 <= k < |s| ==> s[k] <= x
  ensures Sorted(s + [x])
{
  forall p, q | 0 <= p < q < |s + [x]|
    ensures (s + [x])[p] <= (s + [x])[q]
  {
    if q < |s| {
      assert 0 <= p < q < |s|;
      assert (s + [x])[p] == s[p];
      assert (s + [x])[q] == s[q];
    } else {
      assert q == |s|;
      assert p < |s|;
      assert (s + [x])[p] == s[p];
      assert (s + [x])[q] == x;
    }
  }
}

method MergeSorted(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
{
  var i := 0;
  var j := 0;
  out := [];

  while i < |a| || j < |b|
    invariant 0 <= i <= |a|
    invariant 0 <= j <= |b|
    invariant Sorted(out)
    invariant multiset(out) ==
      multiset(a[..i]) + multiset(b[..j])
    invariant forall k :: i <= k < |a| ==>
      |out| == 0 || out[|out| - 1] <= a[k]
    invariant forall k :: j <= k < |b| ==>
      |out| == 0 || out[|out| - 1] <= b[k]
    decreases |a| - i + |b| - j
  {
    if i < |a| && (j == |b| || a[i] <= b[j]) {
      var x := a[i];

      if |out| > 0 {
        SortedToLast(out);
        assert out[|out| - 1] <= x;
        assert forall k :: 0 <= k < |out| ==>
          out[k] <= out[|out| - 1];
      }
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      AppendPreservesSorted(out, x);

      SortedFromIndex(a, i);
      assert forall k :: i < k < |a| ==> x <= a[k];

      if j < |b| {
        assert x <= b[j];
        SortedFromIndex(b, j);
        assert forall k :: j <= k < |b| ==> b[j] <= b[k];
      }
      assert forall k :: j <= k < |b| ==> x <= b[k];

      assert a[..i + 1] == a[..i] + [x];
      calc {
        multiset(out + [x]);
        == multiset(out) + multiset([x]);
        == (multiset(a[..i]) + multiset(b[..j])) + multiset([x]);
        == (multiset(a[..i]) + multiset([x])) + multiset(b[..j]);
        == multiset(a[..i] + [x]) + multiset(b[..j]);
        == multiset(a[..i + 1]) + multiset(b[..j]);
      }

      out := out + [x];
      i := i + 1;

      assert out[|out| - 1] == x;
      assert forall k :: i <= k < |a| ==>
        out[|out| - 1] <= a[k];
      assert forall k :: j <= k < |b| ==>
        out[|out| - 1] <= b[k];
    } else {
      assert j < |b|;
      var x := b[j];

      if |out| > 0 {
        SortedToLast(out);
        assert out[|out| - 1] <= x;
        assert forall k :: 0 <= k < |out| ==>
          out[k] <= out[|out| - 1];
      }
      assert forall k :: 0 <= k < |out| ==> out[k] <= x;
      AppendPreservesSorted(out, x);

      SortedFromIndex(b, j);
      assert forall k :: j < k < |b| ==> x <= b[k];

      if i < |a| {
        assert b[j] < a[i];
        SortedFromIndex(a, i);
        assert forall k :: i <= k < |a| ==> a[i] <= a[k];
      }
      assert forall k :: i <= k < |a| ==> x <= a[k];

      assert b[..j + 1] == b[..j] + [x];
      calc {
        multiset(out + [x]);
        == multiset(out) + multiset([x]);
        == (multiset(a[..i]) + multiset(b[..j])) + multiset([x]);
        == multiset(a[..i]) + (multiset(b[..j]) + multiset([x]));
        == multiset(a[..i]) + multiset(b[..j] + [x]);
        == multiset(a[..i]) + multiset(b[..j + 1]);
      }

      out := out + [x];
      j := j + 1;

      assert out[|out| - 1] == x;
      assert forall k :: i <= k < |a| ==>
        out[|out| - 1] <= a[k];
      assert forall k :: j <= k < |b| ==>
        out[|out| - 1] <= b[k];
    }
  }

  assert i == |a|;
  assert j == |b|;
  assert a[..i] == a;
  assert b[..j] == b;
}

