lemma SwapPreservesMultiset(s: seq<int>, i: int, j: int)
  requires 0 <= i < j < |s|
  ensures multiset(s[i := s[j]][j := s[i]]) == multiset(s)
{
  var t := s[i := s[j]][j := s[i]];
  var p := s[..i];
  var m := s[i + 1..j];
  var q := s[j + 1..];

  assert s == p + [s[i]] + m + [s[j]] + q;
  assert t == p + [s[j]] + m + [s[i]] + q;

  calc {
    multiset(t);
    == multiset(p) + multiset([s[j]]) + multiset(m)
       + multiset([s[i]]) + multiset(q);
    == multiset(p) + multiset([s[i]]) + multiset(m)
       + multiset([s[j]]) + multiset(q);
    == multiset(s);
  }
}

