method ReverseInPlace(a: array<int>)
  modifies a
  ensures forall i :: 0 <= i < a.Length ==> a[i] == old(a[a.Length - 1 - i])
{
  var n := a.Length;
  var i := 0;
  while i < n / 2
    invariant 0 <= i <= n / 2
    invariant forall k :: 0 <= k < i ==> a[k] == old(a[n - 1 - k]) && a[n - 1 - k] == old(a[k])
    invariant forall k :: i <= k < n - i ==> a[k] == old(a[k])
  {
    var tmp := a[i];
    a[i] := a[n - 1 - i];
    a[n - 1 - i] := tmp;
    i := i + 1;
  }
  forall k | 0 <= k < n
    ensures a[k] == old(a[n - 1 - k])
  {
    if k < i {
    } else if k >= n - i {
      var k' := n - 1 - k;
      assert 0 <= k' < i;
      assert a[n - 1 - k'] == old(a[k']);
      assert n - 1 - k' == k;
    } else {
      assert k == n - 1 - k;
      assert a[k] == old(a[k]);
    }
  }
}

