  var hi := a.Length - 1;

  while lo < hi
    invariant 0 <= lo <= a.Length
    invariant -1 <= hi < a.Length
    invariant hi == a.Length - 1 - lo
    invariant forall k :: 0 <= k < lo ==>
      a[k] == old(a[a.Length - 1 - k])
    invariant forall k :: hi < k < a.Length ==>
      a[k] == old(a[a.Length - 1 - k])
    invariant forall k :: lo <= k <= hi ==> a[k] == old(a[k])
    decreases hi - lo
  {
    assert 0 <= lo < hi < a.Length;
    assert a[lo] == old(a[lo]);
    assert a[hi] == old(a[hi]);
    assert hi == a.Length - 1 - lo;
    assert lo == a.Length - 1 - hi;

    var left := a[lo];
    var right := a[hi];

    a[lo] := right;
    a[hi] := left;

    assert a[lo] == old(a[hi]);
    assert a[hi] == old(a[lo]);
    assert a[lo] == old(a[a.Length - 1 - lo]);
    assert a[hi] == old(a[a.Length - 1 - hi]);

    forall k | 0 <= k < lo + 1
      ensures a[k] == old(a[a.Length - 1 - k])
    {
      if k < lo {
      } else {
        assert k == lo;
      }
    }

    forall k | hi - 1 < k < a.Length
      ensures a[k] == old(a[a.Length - 1 - k])
    {
      if hi < k {
      } else {
        assert k == hi;
      }
    }

    forall k | lo + 1 <= k <= hi - 1
      ensures a[k] == old(a[k])
    {
      assert lo < k < hi;
    }

    lo := lo + 1;
    hi := hi - 1;
  }

  assert hi <= lo;

  forall k | 0 <= k < a.Length
    ensures a[k] == old(a[a.Length - 1 - k])
